def seed_base_curriculum(db) -> list:
    """
    Installs the base curriculum: the foundation the learning loop builds on. Base
    topics stay in rotation permanently and every AI-generated topic traces back
    to one of them.

    Runs on every start and only adds the topic_keys that are missing, so topics
    added to SEED_TOPICS later also reach existing databases. Topics already
    present (including ones the user retired) are left exactly as they are.
    Returns the titles that were added.
    """
    from database.models import ContentTopic
    existing = {key for (key,) in db.query(ContentTopic.topic_key).all()}
    created = []
    for topic_data in SEED_TOPICS:
        if topic_data["topic_key"] in existing:
            continue
        topic = ContentTopic(
            category=topic_data["category"],
            topic_key=topic_data["topic_key"],
            title=topic_data["title"],
            core_concept=topic_data["core_concept"],
            visual_blueprint=topic_data["visual_blueprint"],
            weight=topic_data["weight"],
            source="seed",
            is_active=True,
        )
        db.add(topic)
        created.append(topic)
    if not created:
        return []
    db.flush()
    # A base topic is its own base, so variants and bases group uniformly.
    for topic in created:
        topic.base_topic_id = topic.id
    db.commit()
    return [t.title for t in created]
